// Shared seeds for the generation runner and batch worker tests (batch-autogenerate tasks 3.3-4.7):
// a team with a show whose `slate` button carries a generation instruction, an anchored
// transcript, auto-generated and manual events, an admin with a saved AI SDK credential on a fake
// provider, and the fake provider's lifecycle.

import { type FakeLlm, type FakeScript, startFakeLlm } from './fakeLlm';
import { envWith, env as harnessEnv } from './harness';
import { catalogFor, loginCookie, seededSession, seedUser, testDb } from './helpers';
import { saveSdkCredential } from './llmRoutes';
import { harnessHub } from './session/sessionRows';

export const GEN_CATEGORIES_JSON = JSON.stringify([
  {
    id: 'slate',
    name: 'SLATE',
    color: '#ff0000',
    type: 'BUTTON',
    dropdown_options: [],
    on_label: '',
    off_label: '',
    auto_instruction: 'Log every slate.',
  },
]);

/** A session of a fresh team whose show has the instruction-bearing `slate` button. */
export async function genSession(): Promise<{
  studioId: string;
  showId: string;
  sessionId: string;
}> {
  return seededSession({ categoriesJson: GEN_CATEGORIES_JSON });
}

export async function seedAnchoredTranscript(sessionId: string): Promise<void> {
  const hub = await harnessHub(sessionId);
  await hub.replaceTranscriptWords([
    { session_time: '00:00:01:00', speaker: 'A', word: 'roll', start_sec: 1, end_sec: 2 },
    { session_time: '00:00:03:00', speaker: 'A', word: 'slate', start_sec: 3, end_sec: 4 },
    { session_time: '00:00:05:00', speaker: 'B', word: 'marker', start_sec: 5, end_sec: 6 },
  ]);
}

/** An event in `slate`: auto-generated by `runId`, or manual when `runId` is null. */
export async function addSlateEvent(
  sessionId: string,
  message: string,
  runId: string | null,
): Promise<string> {
  const r = await (await harnessHub(sessionId)).addEvent({
    category: 'slate',
    message,
    metadataJson:
      runId === null ? '{}' : JSON.stringify({ auto_generated: true, auto_generate_run_id: runId }),
    markedAtUtc: null,
    ctx: { frameRate: 24, startOffsetFrames: 0 },
    explicitAnchor: { timecodeTotalFrames: 48, wallTimeUtc: '2026-01-01T00:00:02.000Z' },
  });
  return (r as { event: { event_id: string } }).event.event_id;
}

export async function listEvents(sessionId: string) {
  return (await (await harnessHub(sessionId)).listEvents({ limit: 1000, offset: 0 })).events;
}

/** Bumps a row's version, as a person's edit does (session-row-versions). */
export async function markEdited(table: 'session_events' | 'session_topics', id: string) {
  await testDb().run(`UPDATE ${table} SET version = version + 1 WHERE id = ?`, id);
}

/** An admin of `studioId` with a saved AI SDK credential on `baseURL`. */
export async function sdkAdmin(
  studioId: string,
  baseURL: string,
  opts: { email?: string; apiKey?: string } = {},
): Promise<string> {
  const uid = await seedUser({ email: opts.email });
  await catalogFor().auth.authAddMembershipWithRole(uid, studioId, 'admin');
  await saveSdkCredential(baseURL, { cookie: await loginCookie(uid), apiKey: opts.apiKey });
  return uid;
}

/** The env the SDK runner tests use (loopback provider allowed). */
export const sdkEnv = () => envWith({ HOST: '127.0.0.1' });
export { harnessEnv };

const fakes: FakeLlm[] = [];
export async function fakeProvider(script: FakeScript): Promise<FakeLlm> {
  const f = await startFakeLlm(script);
  fakes.push(f);
  return f;
}
export async function closeFakes(): Promise<void> {
  await Promise.all(fakes.splice(0).map((f) => f.close()));
}
